head.script:
scwin.onpageload = function() {}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //pc
    //WebSquare.wUnit.addCommand("set", "wframe1_wframe1_repeat1_0_selectbox1_main_tbody.click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wframe1_'+$p.id+'wframe1_repeat1_0_selectbox1_itemTable_1').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wframe1_'+$p.id+'wframe1_repeat1_0_selectbox1').setValue(1)");
    WebSquare.wUnit.addCommand("pause", "500");
    //pc
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'wframe1_wframe1_repeat1_0_selectbox1_label')).text() == '1'", "true");
    //mobile
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wframe1_'+$p.id+'wframe1_repeat1_0_selectbox1').selectedIndex == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
